{
  "apiVersion": 1,
  "type": "hook.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "useFocusTrap",
    "displayName": "useFocusTrap",
    "keywords": [
      "focus",
      "trap",
      "modal",
      "dialog",
      "accessibility",
      "a11y",
      "keyboard",
      "tab",
      "escape",
      "wai-aria"
    ],
    "params": [
      {
        "name": "options",
        "type": "UseFocusTrapOptions",
        "description": "Configuration object for the focus trap.",
        "required": true
      },
      {
        "name": "options.isActive",
        "type": "boolean",
        "description": "Whether the focus trap is currently active.",
        "required": true
      },
      {
        "name": "options.onEscape",
        "type": "() => void",
        "description": "Callback when Escape key is pressed inside the trapped container.",
        "required": false
      }
    ],
    "returns": [
      {
        "name": "containerRef",
        "type": "React.RefObject<HTMLElement | null>",
        "description": "Ref to attach to the container element that should trap focus."
      },
      {
        "name": "focusFirst",
        "type": "() => void",
        "description": "Focuses the first focusable element inside the container."
      }
    ],
    "usage": {
      "description": "Traps focus within a container element following the WAI-ARIA dialog focus trap pattern. Listens to focus events on the document and redirects focus back into the container if a Tab from inside it moves focus out. Handles both Tab and Shift+Tab wrapping. A Tab pressed while focus is outside the container is left to the page, so an open non-modal surface never takes over the focus order of the page. When the trap deactivates or unmounts, focus is restored to the element that was focused before activation, unless focus was already moved elsewhere or never entered the trap (so popups that keep focus on their trigger, like comboboxes, are unaffected). Mouse clicks outside the container are not intercepted; use a light-dismiss handler for that.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Call focusFirst() when opening a dialog/modal to move focus into the trapped region."
        },
        {
          "guidance": true,
          "description": "Provide an onEscape callback to close the dialog when Escape is pressed."
        },
        {
          "guidance": true,
          "description": "Rely on the built-in focus restoration on close; only add your own onHide focus handling when you need to send focus somewhere other than the previously-focused element."
        },
        {
          "guidance": false,
          "description": "Use on non-modal content like tooltips or dropdowns; those need light-dismiss, not focus trapping."
        }
      ]
    },
    "relatedComponents": [
      "Dialog",
      "DatePicker"
    ],
    "relatedHooks": [
      "useListFocus",
      "useScrollLock"
    ],
    "importPath": "@astryxdesign/core/hooks",
    "category": "focus"
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
